def max_coins(nums):
    vals = [1] + nums + [1]

    def best(l, r):            # burst everything strictly between l and r
        if r - l < 2:
            return 0
        return max(best(l, k) + vals[l] * vals[k] * vals[r] + best(k, r)
                   for k in range(l + 1, r))
    return best(0, len(vals) - 1)

